            "desc": "满纸荒唐言，一把辛酸泪，都云作者痴，谁解其中味？在中国文学史上，很多研究者都认为，《红楼梦》是旧时所有小说中文学成就与艺术成就最高的一部，是中国古典小说的最高峰。不过，很多朋友对于《红楼梦》的主要故事，却知之甚少。红楼梦的妙处并不是它的大戏剧结构，而是在于它细节的丰富。在于它的悲中带喜，喜中有悲，充满了丰富性和世俗性。是在大俗中展现的大雅，是诞生于日常现实生活中的浪漫主义，在含蓄与丰富中传达悲叹的极上妙处。\n\n这次的合集重新做了后期，且修正了之前视频中的问题，喜欢的话，还请三连支持一波哈~",
            "pubdate": 1592740099
