function getCategoryFallbackList(platform = 'Bilibili', category = 'all', timeRange = 'all') {
    const pLower = (platform || 'bilibili').toLowerCase();
    const catLower = (category || 'all').toLowerCase();
    const isStrict = Boolean(timeRange && timeRange !== 'all');
    const now = Math.floor(Date.now() / 1000);

    let rawList = [];

    if (pLower.includes('bili') || pLower.includes('哔哩')) {
        const catList = BILIBILI_CATEGORIES[catLower] || BILIBILI_CATEGORIES.all || [];
        rawList = catList.map((item, idx) => {
            const rel = item.relativeDays || (idx * 0.1 + 0.1);
            const pubdate = (item.pubdate && Number(item.pubdate) > 1e8) ? Number(item.pubdate) : computeDynamicPubdate(rel, now);
            return {
                id: item.id,
                title: item.title,
                description: item.desc || item.title,
                cover: item.cover,
                duration: item.duration || '04:00',
                playCount: formatHeatChinese(item.playRaw),
                commentCount: item.commentCount || '1000',
                author: item.author,
                url: item.url || `https://www.bilibili.com/video/${item.id}`,
                platform: '哔哩哔哩',
                playRaw: item.playRaw,
                pubdate
            };
        });
    } else if (pLower.includes('douyin') || pLower.includes('抖音')) {
        let douyinPool = MULTI_PLATFORM_FALLBACK.douyin || {};
        try {
            const fs = require('fs');
            const path = require('path');
            const raw = fs.readFileSync(path.join(__dirname, '..', 'douyin_verified_categories.json'), 'utf8');
            douyinPool = JSON.parse(raw);
        } catch (e) {}

        const list = douyinPool[catLower] || douyinPool.all || [];
        rawList = list.map((item, idx) => {
            const rel = item.relativeDays || (idx * 0.1 + 0.1);
            const pubdate = (item.pubdate && Number(item.pubdate) > 1e8) ? Number(item.pubdate) : computeDynamicPubdate(rel, now);
            return {
                id: item.id || `dy_${catLower}_${idx}`,
                title: item.title,
                description: item.title,
                cover: item.cover,
                duration: item.duration || '00:30',
                playCount: formatHeatChinese(item.playRaw),
                commentCount: item.commentCount || '3500',
                author: item.author || '抖音热搜',
                url: item.url || `https://www.douyin.com/search/${encodeURIComponent(item.title)}?type=video`,
                platform: '抖音',
                playRaw: item.playRaw,
                pubdate
            };
        });
    } else {
        let platformKey = 'douyin';
        if (pLower.includes('youtube') || pLower.includes('油管')) platformKey = 'youtube';
        else if (pLower.includes('tiktok')) platformKey = 'tiktok';
        else if (pLower.includes('twitter') || pLower === 'x') platformKey = 'twitter';
        else if (pLower.includes('xiaohongshu') || pLower.includes('小红书') || pLower === 'xhs') platformKey = 'xiaohongshu';
        else if (pLower.includes('kuaishou') || pLower.includes('快手') || pLower === 'ks') platformKey = 'kuaishou';

        const platformPool = MULTI_PLATFORM_FALLBACK[platformKey] || MULTI_PLATFORM_FALLBACK.douyin || {};
        let list = platformPool[catLower] || platformPool.all || [];
        if (catLower === 'all' && list.length < 15) {
            const aggregated = [];
            for (const catKey of Object.keys(platformPool)) {
                if (Array.isArray(platformPool[catKey])) {
                    aggregated.push(...platformPool[catKey]);
                }
            }
            if (aggregated.length > list.length) list = aggregated;
        }
        rawList = list.map((item, idx) => {
            const rel = item.relativeDays || (idx * 0.1 + 0.1);
            const pubdate = (item.pubdate && Number(item.pubdate) > 1e8) ? Number(item.pubdate) : computeDynamicPubdate(rel, now);
            return {
                id: item.id || `${platformKey}_${idx}`,
                title: item.title,
                description: item.description || item.title,
                cover: item.cover,
                duration: item.duration || 'Shorts',
                playCount: formatHeatChinese(item.playRaw),
                commentCount: item.commentCount || '1000',
                author: item.author || `${platformKey}创作者`,
                url: item.url || (platformKey === 'youtube' ? `https://www.youtube.com/watch?v=${item.id}` : `https://www.douyin.com/search/${encodeURIComponent(item.title)}?type=video`),
                platform: platformKey === 'youtube' ? 'YouTube' : (platformKey === 'tiktok' ? 'TikTok' : (platformKey === 'twitter' ? 'Twitter' : (platformKey === 'xiaohongshu' ? '小红书' : (platformKey === 'kuaishou' ? '快手' : 'Universal')))),
                playRaw: item.playRaw,
                pubdate
            };
        });
    }

    return prepareVideoList(rawList, { timeRange, requireKnownDate: isStrict, limit: 60 });
}


function getTopicLeaderboardList(platform = 'all', category = 'all') {
    const catLower = (category || 'all').toLowerCase();
    let topics = EVENT_TOPIC_TEMPLATES;
    if (catLower && catLower !== 'all') {
        const filtered = topics.filter(t => t.category === catLower);
        if (filtered.length > 0) topics = filtered;
    }
    return topics.map((item, idx) => ({
        id: item.id,
        title: item.title,
        tag: item.tag || '🔥 热门',
        category: item.category,
        heatRaw: item.heatRaw,
        heatDisplay: formatHeatChinese(item.heatRaw),
        worksCount: item.worksCount,
        desc: item.desc,
        rank: idx + 1,
        subVideos: (item.subVideos || []).map(v => ({
            ...v,
            playDisplay: formatHeatChinese(v.playRaw)
        }))
    }));
}

module.exports = {
    BILIBILI_CATEGORIES,
    EVENT_TOPIC_TEMPLATES,
    getCategoryFallbackList,
    getTopicLeaderboardList
};
